/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: db, mutation, deferred, request, send, discard, createBody, create, createRouted, current, edit,
 *              stored, lookupRecord, catalogSnapshot, slotsSnapshot, eligibility
 *   Constants: actor, other, user, album, artist, first, second, albumTitle, discarded, tombstoneKeys, provider
 *   Variables: harness, server, guard, base, token, otherToken, userToken
 * Tests
 *   - the discard route guards authentication, the current admin and the viewer before parsing, stays private and within 96 KB, and refuses a malformed body or ID
 *   - a discard replaces the review with a tombstone of only the listed keys, deletes its lookup record and leaves every catalog document byte-equal
 *   - a discard replays its original intent with the same body; another intent, another administrator or another body on a discarded review is reported as discarded
 *   - an operation ID already used by a receipt, a recovery receipt or an automatic receipt of the review is an operation conflict that writes nothing
 *   - a discard binds the last administrator change: a revision before it or beyond the current one conflicts, while Luna and lookup progress do not
 *   - an applied review cannot be discarded, even with a stale revision, and a newer-format review asks for a reload
 *   - a discard is refused while Luna is queued or running, and admitted once Luna AI is stopped even while its call still settles, whose late answer writes nothing
 *   - a review at its receipt limit, a changed source and an unavailable source can each be discarded
 *   - every other route reports a discarded review as discarded and changes nothing, and its candidate artwork preview stays a bodiless not found
 *   - after a discard the eligibility opens the other open completion or none, and the list and its counts leave the discarded one out while items carry the catalog Album title
 *   - a replayed creation of a discarded review is reported as discarded, another body with its operation ID conflicts, and nothing is inserted
 *   - a lookup step in flight when a review is discarded stores nothing and the worker ends the run without another request
 *   - a queued or a retrying review run removed by a discard is never claimed
 *   - an apply and a discard of one review started together take effect exactly once
 *   - two discards of one intent sent together both answer the original result, and of two intents sent together exactly one is admitted
 *   - a discard whose lookup-record deletion fails writes nothing, and the same request is then admitted once
 * @end-catalog */

/**
 * Discarding an unapplied existing-Album review against a MongoDB replica set: the private route and its limits, the tombstone that
 * replaces the review and the lookup record deleted with it in one transaction, replays and other intents (also sent together), the
 * refusal order (applied, operation ID, newer format, revision, Luna queued or running), a stopped Luna call and a lookup step still
 * in flight that store nothing, every other review route reporting the review as discarded, creation replays, the review queue and
 * eligibility, an apply racing a discard, and a failed lookup-record deletion that writes nothing. Lookup runs use fixture MusicBrainz
 * answers. All names, identifiers and accounts are synthetic.
 */
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { after, before, beforeEach, mock, test } from 'node:test';
import type { Server } from 'node:http';
import { Collection, ObjectId } from 'mongodb';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { createSession } from '../../src/services/auth/authSessionService';
import { adminCatalogItemRevision } from '../../src/administration/catalog/adminCatalogService';
import { analyzeCatalogReview, cancelCatalogReviewAnalysis, createCatalogReview, editCatalogReview, getCatalogReview } from '../../src/administration/catalog/adminCatalogReviewService';
import { adminImportIndexes, createAdminImport, importCollection, initializeAdminImportStorage, runAdminImportWorkerOnce } from '../../src/administration/import/adminImportService';
import type { ImportAnalysisProvider } from '../../src/administration/import/adminImportProvider';
import type { CatalogReviewField, CatalogReviewResponse } from '../../src/administration/catalog/adminCatalogReviewContract';
import { createMusicBrainzClient, type MusicBrainzClient } from '../../src/administration/lookup/musicBrainzClient';
import { runMetadataLookupOnce } from '../../src/administration/lookup/metadataLookupService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import { installNetworkGuard } from '../support/networkGuard';
import { emptyItunesClient, fixtureTransport, immediateGate } from '../support/metadataLookupFixtures';
import { drainLookup, lookupMbid, pairableRelease, reviewSearches, withLookup } from '../support/catalogReviewRunFixtures';

let harness: MongoReplicaSetHarness, server: Server, guard: ReturnType<typeof installNetworkGuard>, base = '', token = '', otherToken = '', userToken = '';
const actor = new ObjectId(), other = new ObjectId(), user = new ObjectId(), album = new ObjectId(), artist = new ObjectId(), first = new ObjectId(), second = new ObjectId();
const db = () => getDb()!, mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const albumTitle: CatalogReviewField = { scope: 'album', slotId: null, field: 'title' };
const discarded = { status: 404, body: { code: 'ADMIN_CATALOG_REVIEW_DISCARDED' } };
const tombstoneKeys = ['_id', 'actorId', 'albumId', 'createdAt', 'discardedAt', 'discardedBy', 'purpose', 'receipts', 'revision', 'updatedAt'];
/** A Luna provider that proposes a new Album title. */
const provider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album
    ? [{ scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Proposed Album', source: 'context', evidence: 'Existing title' }] : [] };
const deferred = () => { let resolve!: () => void; const promise = new Promise<void>(settle => { resolve = settle; }); return { resolve, promise }; };
const request = (path: string, method = 'GET', body?: unknown, access = token) => fetch(base + '/api/admin/v1' + path, { method,
    headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json' }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
/** Sends `body` and reads the status and JSON answer. */
const send = async (path: string, method: string, body?: unknown, access = token) => { const response = await request(path, method, body, access); return { status: response.status, body: await response.json() }; };
const discard = (id: string, body: unknown, access = token) => send(`/catalog-reviews/${id}/discard`, 'POST', body, access);
/** A creation body for the Album at its current revision; `another` is true unless given (null leaves it out). */
const createBody = async (another: boolean | null = true) => ({ operationId: randomUUID(), albumId: String(album),
    expectedRevision: adminCatalogItemRevision('album', await db().collection('albums').findOne({ _id: album })), ...(another === null ? {} : { another }) });
/** A review created without its automatic lookup run (format 2), as the review service creates it. */
const create = async () => createCatalogReview(String(actor), await createBody());
/** A review created through the route, which queues its automatic run where lookup is available. */
const createRouted = async (another: boolean | null = true) => {
    const created = await send('/catalog-reviews', 'POST', await createBody(another));
    assert.equal(created.status, 201); return created.body as CatalogReviewResponse;
};
const current = (id: string) => getCatalogReview(String(actor), id);
const edit = (result: CatalogReviewResponse, change: (draft: CatalogReviewResponse['item']['draft']) => void) => {
    const draft = structuredClone(result.item.draft); change(draft); return editCatalogReview(String(actor), result.item.id, { ...mutation(result.item.revision), draft });
};
const stored = (id: string) => db().collection('adminAlbumImports').findOne({ _id: new ObjectId(id) });
const lookupRecord = (id: string) => db().collection('adminImportLookups').findOne({ _id: new ObjectId(id) });
const catalogSnapshot = async () => JSON.stringify(await Promise.all(['albums', 'audioTracks', 'artists', 'organizations']
    .map(async name => [name, await db().collection(name).find({}).sort({ _id: 1 }).toArray()])));
const slotsSnapshot = () => db().collection('adminImportAnalysisSlots').find({}).sort({ _id: 1 }).toArray();
const eligibility = async () => (await send(`/catalog-reviews/eligibility?albumId=${album}`, 'GET')).body;

before(async () => {
    harness = await startMongoReplicaSet('archtree-catalog-review-discard-test');
    for (const index of adminImportIndexes) await db().collection(index.collection).createIndex(index.keys, index.options);
    server = await new Promise(resolve => { const active = createApp().listen(0, '127.0.0.1', () => resolve(active)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
    guard = installNetworkGuard();
});
beforeEach(async () => {
    for (const name of ['users', 'authSessions', 'adminAlbumImports', 'adminImportAnalysisSlots', 'albums', 'artists', 'audioTracks', 'organizations', 'adminImportLookups', 'adminMetadataLookupGates']) {
        await db().collection(name).deleteMany({});
    }
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true';
    const account = { _id: actor, email: 'discard-admin@example.test', emailVerified: true, role: 'admin' }, colleague = { _id: other, email: 'discard-other@example.test', emailVerified: true, role: 'admin' };
    const ordinary = { _id: user, email: 'discard-user@example.test', emailVerified: true, role: 'user' };
    await db().collection('users').insertMany([account, colleague, ordinary]);
    token = (await createSession(account)).accessToken; otherToken = (await createSession(colleague)).accessToken; userToken = (await createSession(ordinary)).accessToken;
    await db().collection('artists').insertOne({ _id: artist, name: 'Existing Artist', lifecycleStatus: 'ready', visibility: 'hidden' });
    await db().collection('albums').insertOne({ _id: album, title: 'Existing Album', releaseDate: { year: 2020 }, visibility: 'hidden', lifecycleStatus: 'ready', audioTrackIds: [String(first), String(second)],
        credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented', coverArtUrl: 'unchanged' });
    await db().collection('audioTracks').insertMany([first, second].map((id, index) => ({ _id: id, title: `Track ${index + 1}`, originalFileName: index ? undefined : '01 - Original.mp3',
        trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(id), albumId: String(album), visibility: 'public', mediaType: 'audio', duration: '1:00' })));
    await initializeAdminImportStorage(db());
});
after(async () => {
    guard?.restore(); assert.deepEqual(guard?.attempts ?? [], []);
    await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop(); delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
});

test('the discard route guards authentication, the current admin and the viewer before parsing, stays private and within 96 KB, and refuses a malformed body or ID', async () => {
    const review = await create(), id = review.item.id, path = `/api/admin/v1/catalog-reviews/${id}/discard`, before = await stored(id);
    const raw = (body: string, headers: Record<string, string>) => fetch(base + path, { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, body });
    const anonymous = await raw('{broken', {});
    assert.deepEqual([anonymous.status, anonymous.headers.get('cache-control')], [401, 'private, no-store']);
    assert.equal((await raw('{broken', { Authorization: `Bearer ${userToken}` })).status, 403);
    // A same-origin browser session naming another account as its viewer is refused before the body is read.
    assert.equal((await raw('{broken', { Cookie: `session_token=${token}`, Origin: base, 'X-Finitude-Account-Viewer': String(other) })).status, 409);
    // The body is two fields: over 96 KB is refused, while 90 KB reaches the parser, which refuses the unknown key.
    assert.equal((await request(`/catalog-reviews/${id}/discard`, 'POST', { ...mutation(1), padding: 'p'.repeat(97 * 1024) })).status, 413);
    for (const body of [{ ...mutation(1), padding: 'p'.repeat(90 * 1024) }, { ...mutation(1), another: true }, { operationId: 'not-a-uuid', expectedRevision: 1 }, { ...mutation(0) },
        { operationId: randomUUID() }, { expectedRevision: 1 }, [mutation(1)]]) {
        const refused = await discard(id, body);
        assert.deepEqual([refused.status, refused.body], [400, { code: 'ADMIN_IMPORT_INVALID_INPUT' }], JSON.stringify(body).slice(0, 60));
    }
    assert.equal((await raw('{broken', { Authorization: `Bearer ${token}` })).status, 400);
    // A malformed or unknown ID, or an import's, is not found; the import stays as it was.
    const imported = await createAdminImport(String(actor), { operationId: randomUUID(), manifest: { rootLabel: 'Folder', files: [{ slotId: randomUUID(), filename: 'Song.mp3', relativePath: 'Song.mp3', byteLength: 1 }] } });
    const importBefore = await stored(imported.item.id);
    for (const target of ['bad', String(new ObjectId()), imported.item.id]) {
        const missing = await discard(target, mutation(1));
        assert.deepEqual([missing.status, missing.body], [404, { code: 'ADMIN_CATALOG_REVIEW_NOT_FOUND' }], target);
    }
    assert.deepEqual(await stored(imported.item.id), importBefore);
    assert.deepEqual(await stored(id), before, 'no refusal wrote anything');
    // An administrator who lost the role is refused before anything is read.
    await db().collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    assert.equal((await discard(id, mutation(1))).status, 403);
    await db().collection('users').updateOne({ _id: actor }, { $set: { role: 'admin' } });
    const admitted = await request(`/catalog-reviews/${id}/discard`, 'POST', mutation(1));
    assert.equal(admitted.status, 200); assert.match(admitted.headers.get('cache-control')!, /no-store/);
});

test('a discard replaces the review with a tombstone of only the listed keys, deletes its lookup record and leaves every catalog document byte-equal', () => withLookup(async () => {
    const created = await createRouted(), id = created.item.id;
    await drainLookup([...reviewSearches([[lookupMbid(1), 2]]), ...pairableRelease(lookupMbid(1))]);
    const looked = await current(id);
    assert.deepEqual([(await lookupRecord(id))?.state, looked.item.draft.album.label?.name], ['complete', 'Looked Up Label']);
    const saved = await send(`/catalog-reviews/${id}`, 'PATCH', { ...mutation(looked.item.revision), changes: [{ path: 'album.title', base: 'Existing Album', value: 'Saved Album Title' }] });
    assert.equal(saved.status, 200);
    const revision = saved.body.item.revision as number, review = (await stored(id))!, catalog = await catalogSnapshot(), slots = await slotsSnapshot();
    const body = mutation(revision), answer = await discard(id, body);
    assert.deepEqual(answer, { status: 200, body: { discarded: { id, albumId: String(album) }, receipt: { operationId: body.operationId, kind: 'discard', revision: revision + 1 } } });
    const tombstone = (await stored(id))!;
    assert.deepEqual(Object.keys(tombstone).sort(), tombstoneKeys);
    const creation = review.receipts.find((receipt: { kind: string }) => receipt.kind === 'create');
    assert.deepEqual(tombstone, { _id: review._id, purpose: 'catalogReviewDiscarded', actorId: String(actor), createdAt: review.createdAt, updatedAt: tombstone.discardedAt,
        revision: revision + 1, albumId: String(album), discardedAt: tombstone.discardedAt, discardedBy: String(actor),
        receipts: [{ operationId: creation.operationId, kind: 'create', revision: creation.revision, actorId: creation.actorId, hash: creation.hash, at: creation.at },
            { operationId: body.operationId, kind: 'discard', revision: revision + 1, actorId: String(actor), hash: tombstone.receipts[1].hash, at: tombstone.discardedAt }] });
    const wire = JSON.stringify(tombstone);
    for (const forbidden of ['Existing Album', 'Saved Album Title', 'Looked Up', 'Track 1', '01 - Original.mp3', 'draft', 'catalogCapture', 'manifest', 'analysis', 'suggestions', 'lookupGate']) {
        assert.equal(wire.includes(forbidden), false, forbidden);
    }
    assert.equal(await lookupRecord(id), null);
    assert.equal(await catalogSnapshot(), catalog);
    assert.deepEqual(await slotsSnapshot(), slots);
}));

test('a discard replays its original intent with the same body; another intent, another administrator or another body on a discarded review is reported as discarded', async () => {
    const review = await create(), id = review.item.id, body = mutation(1);
    const answer = await discard(id, body);
    assert.equal(answer.status, 200);
    const tombstone = await stored(id);
    assert.deepEqual(await discard(id, body), answer);
    assert.deepEqual(await discard(id, mutation(1)), discarded, 'another intent');
    assert.deepEqual(await discard(id, { operationId: body.operationId, expectedRevision: 2 }), discarded, 'another body');
    assert.deepEqual(await discard(id, body, otherToken), discarded, 'another administrator');
    assert.deepEqual(await stored(id), tombstone);
});

test('an operation ID already used by a receipt, a recovery receipt or an automatic receipt of the review is an operation conflict that writes nothing', async () => {
    const createdBody = await createBody(), review = await createCatalogReview(String(actor), createdBody), id = review.item.id;
    const editBody = { ...mutation(1), draft: { ...review.item.draft, album: { ...review.item.draft.album, title: 'Edited Album' } } };
    await editCatalogReview(String(actor), id, editBody);
    const recovery = randomUUID(), automatic = randomUUID(), receipt = (operationId: string) => ({ operationId, kind: 'cleanup', revision: 2, actorId: String(actor), hash: 'synthetic', at: new Date() });
    await importCollection().updateOne({ _id: new ObjectId(id) }, { $push: { recoveryReceipts: receipt(recovery), automaticReceipts: receipt(automatic) } } as never);
    const before = await stored(id);
    for (const operationId of [createdBody.operationId, editBody.operationId, recovery, automatic]) {
        assert.deepEqual(await discard(id, { operationId, expectedRevision: 2 }), { status: 409, body: { code: 'ADMIN_IMPORT_OPERATION_CONFLICT' } }, operationId);
    }
    assert.deepEqual(await stored(id), before);
});

test('a discard binds the last administrator change: a revision before it or beyond the current one conflicts, while Luna and lookup progress do not', () => withLookup(async () => {
    // Revision 1 is the creation, 2 an edit, 3 the analysis request; the worker's Luna ticks then advance the revision without a receipt.
    const created = await create(), id = created.item.id, edited = await edit(created, draft => { draft.album.title = 'Edited Album'; });
    const analyzed = await analyzeCatalogReview(String(actor), id, mutation(edited.item.revision), provider);
    for (let tick = 0; tick < 5 && (await current(id)).item.analysis.state !== 'complete'; tick++) await runAdminImportWorkerOnce(provider);
    const completed = await current(id);
    assert.deepEqual([analyzed.receipt?.revision, completed.item.analysis.state], [3, 'complete']);
    assert.ok(completed.item.revision > 3);
    const before = await stored(id);
    for (const expectedRevision of [1, 2, completed.item.revision + 1]) {
        assert.deepEqual(await discard(id, { operationId: randomUUID(), expectedRevision }), { status: 409, body: { code: 'ADMIN_IMPORT_REVISION_CONFLICT' } }, String(expectedRevision));
    }
    assert.deepEqual(await stored(id), before);
    assert.equal((await discard(id, mutation(3))).status, 200);
    // A review created with its automatic run: the conversion and the completed run add no receipt, so the creation's revision binds.
    const routed = await createRouted(null), routedId = routed.item.id;
    await drainLookup([...reviewSearches([[lookupMbid(1), 2]]), ...pairableRelease(lookupMbid(1))]);
    assert.deepEqual([routed.receipt?.revision, (await lookupRecord(routedId))?.state], [1, 'complete']);
    assert.ok((await current(routedId)).item.revision > 1);
    assert.equal((await discard(routedId, mutation(1))).status, 200);
}));

test('an applied review cannot be discarded, even with a stale revision, and a newer-format review asks for a reload', async () => {
    const review = await edit(await create(), draft => { draft.album.title = 'Applied Album'; }), id = review.item.id;
    const applied = await send(`/catalog-reviews/${id}/apply`, 'POST', { ...mutation(review.item.revision), fields: [albumTitle] });
    assert.deepEqual([applied.status, applied.body.item.state], [200, 'applied']);
    const before = await stored(id), catalog = await catalogSnapshot();
    for (const expectedRevision of [1, review.item.revision, applied.body.item.revision, applied.body.item.revision + 1]) {
        assert.deepEqual(await discard(id, { operationId: randomUUID(), expectedRevision }), { status: 409, body: { code: 'ADMIN_CATALOG_REVIEW_APPLIED' } }, String(expectedRevision));
    }
    assert.deepEqual([await stored(id), await catalogSnapshot()], [before, catalog]);
    const newer = await create(), newerId = newer.item.id;
    await importCollection().updateOne({ _id: new ObjectId(newerId) }, { $set: { draftVersion: 4 } });
    const saved = await stored(newerId);
    assert.deepEqual(await discard(newerId, mutation(1)), { status: 409, body: { code: 'ADMIN_IMPORT_RELOAD_REQUIRED' } });
    assert.deepEqual(await stored(newerId), saved);
});

test('a discard is refused while Luna is queued or running, and admitted once Luna AI is stopped even while its call still settles, whose late answer writes nothing', async () => {
    const review = await create(), id = review.item.id, _id = new ObjectId(id);
    const queued = await analyzeCatalogReview(String(actor), id, mutation(1), provider), before = await stored(id);
    const active = { status: 409, body: { code: 'ADMIN_IMPORT_ANALYSIS_ACTIVE' } };
    assert.deepEqual(await discard(id, mutation(queued.item.revision)), active, 'queued');
    await importCollection().updateOne({ _id }, { $set: { 'analysis.state': 'running' } });
    assert.deepEqual(await discard(id, mutation(queued.item.revision)), active, 'running');
    await importCollection().updateOne({ _id }, { $set: { 'analysis.state': 'queued' } });
    assert.deepEqual(await stored(id), before, 'no refusal wrote anything');
    // The worker sends the call and waits for its answer; the administrator stops Luna AI meanwhile and then discards.
    const entered = deferred(), release = deferred(); let calls = 0, tombstone: unknown;
    const worker = runAdminImportWorkerOnce({ configured: () => true, analyze: async input => { calls++; entered.resolve(); await release.promise; return provider.analyze(input); } });
    await entered.promise;
    try {
        const running = await current(id);
        assert.equal(running.item.analysis.state, 'running');
        const stopped = await cancelCatalogReviewAnalysis(String(actor), id, mutation(running.item.revision));
        const settling = (await importCollection().findOne({ _id }))!.analysis;
        assert.deepEqual([settling.state, settling.chunks.some(chunk => chunk.state === 'inflight')], ['cancelled', true]);
        assert.equal((await discard(id, mutation(stopped.item.revision))).status, 200);
        tombstone = await stored(id);
    } finally { release.resolve(); assert.equal(await worker, true); }
    assert.equal(calls, 1);
    assert.deepEqual(await stored(id), tombstone);
    // The call still counts against the daily allowance; nothing is refunded.
    assert.equal((await db().collection('adminImportAnalysisSlots').findOne({ _id: `daily:${new Date().toISOString().slice(0, 10)}` as never }))?.attempts, 1);
});

test('a review at its receipt limit, a changed source and an unavailable source can each be discarded', async () => {
    const limited = await create(), limitedId = limited.item.id, original = (await stored(limitedId))!;
    const edits = Array.from({ length: 255 }, (_unused, index) => ({ operationId: randomUUID(), kind: 'edit', revision: 1, actorId: String(actor), hash: `h${index}`, at: new Date() }));
    await importCollection().updateOne({ _id: original._id }, { $set: { receipts: [original.receipts[0], ...edits] } } as never);
    assert.equal((await stored(limitedId))!.receipts.length, 256);
    const atLimit = mutation(1);
    assert.equal((await discard(limitedId, atLimit)).status, 200);
    assert.deepEqual((await stored(limitedId))!.receipts.map((receipt: { kind: string }) => receipt.kind), ['create', 'discard']);
    const changed = await create();
    await db().collection('audioTracks').updateOne({ _id: first }, { $set: { title: 'External edit' } });
    assert.equal((await current(changed.item.id)).item.sourceStatus, 'changed');
    assert.equal((await discard(changed.item.id, mutation(1))).status, 200);
    const unavailable = await create();
    await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'deleting' } });
    assert.equal((await current(unavailable.item.id)).item.sourceStatus, 'unavailable');
    const answer = await discard(unavailable.item.id, mutation(1));
    assert.deepEqual([answer.status, answer.body.discarded], [200, { id: unavailable.item.id, albumId: String(album) }]);
});

test('every other route reports a discarded review as discarded and changes nothing, and its candidate artwork preview stays a bodiless not found', () => withLookup(async () => {
    const created = await createRouted(), id = created.item.id, candidateKey = `musicbrainz:${lookupMbid(1)}`;
    await drainLookup([...reviewSearches([[lookupMbid(1), 2]]), ...pairableRelease(lookupMbid(1))]);
    const saveBody = { ...mutation((await current(id)).item.revision), changes: [{ path: 'album.title', base: 'Existing Album', value: 'Saved Album Title' }] };
    const saved = await send(`/catalog-reviews/${id}`, 'PATCH', saveBody), revision = saved.body.item.revision as number;
    assert.equal(saved.status, 200);
    assert.equal((await discard(id, mutation(revision))).status, 200);
    const tombstone = await stored(id), catalog = await catalogSnapshot();
    const routes: [string, string, unknown][] = [['GET', '', undefined], ['GET', '/lookup', undefined], ['GET', '/candidates', undefined],
        ['PATCH', '', { ...mutation(revision), changes: [{ path: 'album.title', base: 'Saved Album Title', value: 'Saved too late' }] }], ['PATCH', '', saveBody],
        ['POST', '/analyze', mutation(revision)], ['POST', '/adopt', { ...mutation(revision), generation: 1, selectedIds: ['0'.repeat(24)], rejectIds: [] }], ['POST', '/cancel-analysis', mutation(revision)],
        ['POST', '/lookup', { ...mutation(revision), kind: 'album', text: 'Existing Album' }], ['POST', '/lookup/retry', mutation(revision)],
        ['POST', '/lookup/choose', { ...mutation(revision), run: 1, candidateKey: null }],
        ['POST', '/lookup/resolve', { ...mutation(revision), run: 1, candidateKey, answers: [{ path: 'album.title', answer: 'mine', base: 'Saved Album Title' }] }],
        ['POST', '/decisions', { ...mutation(revision), decisions: [] }], ['POST', '/apply', { ...mutation(revision), fields: [albumTitle] }]];
    for (const [method, suffix, body] of routes) {
        // The same request for an unknown review is not found, so each body reaches the review read.
        const unknown = await send(`/catalog-reviews/${new ObjectId()}${suffix}`, method, body);
        assert.equal(unknown.status, 404, `unknown ${method} ${suffix} ${JSON.stringify(unknown.body)}`);
        assert.deepEqual(await send(`/catalog-reviews/${id}${suffix}`, method, body), discarded, `${method} ${suffix}`);
    }
    const artwork = await fetch(`${base}/api/admin/v1/catalog-reviews/${id}/lookup/candidates/${encodeURIComponent(candidateKey)}/artwork`, { headers: { Authorization: `Bearer ${token}` } });
    assert.deepEqual([artwork.status, artwork.headers.get('cache-control'), await artwork.text()], [404, 'private, no-store', '']);
    assert.deepEqual([await stored(id), await catalogSnapshot(), await lookupRecord(id)], [tombstone, catalog, null]);
}));

test('after a discard the eligibility opens the other open completion or none, and the list and its counts leave the discarded one out while items carry the catalog Album title', async () => {
    const a = await create(), b = await create(), edited = await edit(b, draft => { draft.album.title = 'Corrected Album Title'; });
    const list = async () => (await send('/catalog-reviews', 'GET')).body as { items: { id: string; albumId: string; albumTitle: string; title: string }[]; counts: { all: number } };
    const listed = await list(), row = (id: string) => listed.items.find(item => item.id === id);
    assert.deepEqual([row(b.item.id), row(a.item.id)].map(item => [item?.albumId, item?.albumTitle, item?.title]),
        [[String(album), 'Existing Album', 'Corrected Album Title'], [String(album), 'Existing Album', 'Existing Album']]);
    assert.deepEqual([listed.counts.all, (await eligibility()).openReviewId], [2, b.item.id]);
    assert.equal((await discard(b.item.id, mutation(edited.item.revision))).status, 200);
    const afterFirst = await list();
    assert.deepEqual([afterFirst.counts.all, afterFirst.items.map(item => item.id), (await eligibility()).openReviewId], [1, [a.item.id], a.item.id]);
    assert.equal((await discard(a.item.id, mutation(1))).status, 200);
    const afterBoth = await list();
    assert.deepEqual([afterBoth.counts.all, afterBoth.items, await eligibility()], [0, [], { eligible: true, reason: null, openReviewId: null, lookupAvailable: false, openLookup: null }]);
    // With none open, the Album page's action creates a new review without asking for another one.
    const fresh = await createRouted(null);
    assert.equal((await eligibility()).openReviewId, fresh.item.id);
});

test('a replayed creation of a discarded review is reported as discarded, another body with its operation ID conflicts, and nothing is inserted', () => withLookup(async () => {
    const body = await createBody(null), created = await send('/catalog-reviews', 'POST', body), id = created.body.item.id as string;
    assert.deepEqual([created.status, (await lookupRecord(id))?.state], [201, 'queued']);
    assert.equal((await discard(id, mutation(created.body.item.revision))).status, 200);
    const tombstone = await stored(id), count = async () => [await db().collection('adminAlbumImports').countDocuments(), await db().collection('adminImportLookups').countDocuments()];
    assert.deepEqual(await count(), [1, 0]);
    assert.deepEqual(await send('/catalog-reviews', 'POST', body), discarded);
    assert.deepEqual(await send('/catalog-reviews', 'POST', { ...body, another: true }), { status: 409, body: { code: 'ADMIN_IMPORT_OPERATION_CONFLICT' } });
    assert.deepEqual([await count(), await stored(id)], [[1, 0], tombstone]);
}));

test('a lookup step in flight when a review is discarded stores nothing and the worker ends the run without another request', () => withLookup(async () => {
    const created = await createRouted(null), id = created.item.id;
    const fixture = fixtureTransport(reviewSearches()), inner = createMusicBrainzClient({ gate: immediateGate(), transport: fixture.transport, sleep: async () => undefined });
    const entered = deferred(), release = deferred();
    // The search is sent and answered, and its answer waits while the review is discarded.
    const musicBrainz: MusicBrainzClient = { ...inner, async searchReleases(query, options) { const answer = await inner.searchReleases(query, options); entered.resolve(); await release.promise; return answer; } };
    const worker = runMetadataLookupOnce({ musicBrainz, itunes: emptyItunesClient() });
    await entered.promise;
    let tombstone: unknown;
    try {
        assert.equal((await lookupRecord(id))?.state, 'running');
        assert.equal((await discard(id, mutation((await current(id)).item.revision))).status, 200);
        tombstone = await stored(id);
    } finally { release.resolve(); assert.equal(await worker, true); }
    assert.equal(await lookupRecord(id), null);
    assert.equal(fixture.requests.length, 1);
    assert.deepEqual(await stored(id), tombstone);
}));

test('a queued or a retrying review run removed by a discard is never claimed', () => withLookup(async () => {
    const fixture = fixtureTransport([]), musicBrainz = createMusicBrainzClient({ gate: immediateGate(), transport: fixture.transport, sleep: async () => undefined }), itunes = emptyItunesClient();
    const queued = await createRouted(null);
    assert.equal((await lookupRecord(queued.item.id))?.state, 'queued');
    assert.equal((await discard(queued.item.id, mutation(queued.item.revision))).status, 200);
    assert.equal(await runMetadataLookupOnce({ musicBrainz, itunes }), false);
    const retrying = await createRouted(null);
    await db().collection('adminImportLookups').updateOne({ _id: new ObjectId(retrying.item.id) }, { $set: { state: 'retrying', retryAt: new Date(Date.now() - 60_000), leaseUntil: null } });
    assert.equal((await discard(retrying.item.id, mutation(retrying.item.revision))).status, 200);
    assert.equal(await runMetadataLookupOnce({ musicBrainz, itunes }), false);
    assert.deepEqual([fixture.requests, itunes.calls, await db().collection('adminImportLookups').countDocuments()], [[], [], 0]);
}));

test('an apply and a discard of one review started together take effect exactly once', async () => {
    const outcomes: string[] = [];
    for (let n = 0; n < 4; n++) {
        const review = await edit(await create(), draft => { draft.album.title = `Applied ${n}`; }), id = review.item.id, catalog = await catalogSnapshot();
        // Every other round sends the discard first.
        const applying = () => send(`/catalog-reviews/${id}/apply`, 'POST', { ...mutation(review.item.revision), fields: [albumTitle] }), discarding = () => discard(id, mutation(review.item.revision));
        const [applied, dropped] = n % 2 ? await Promise.all([applying(), discarding()]) : (await Promise.all([discarding(), applying()])).reverse();
        assert.equal([applied.status, dropped.status].filter(status => status === 200).length, 1, JSON.stringify([applied, dropped]));
        if (applied.status === 200) {
            assert.deepEqual([dropped, (await db().collection('albums').findOne({ _id: album }))?.title, (await stored(id))?.purpose],
                [{ status: 409, body: { code: 'ADMIN_CATALOG_REVIEW_APPLIED' } }, `Applied ${n}`, 'catalogReview']);
            outcomes.push('apply');
        } else {
            assert.deepEqual([applied, await catalogSnapshot(), (await stored(id))?.purpose], [discarded, catalog, 'catalogReviewDiscarded']);
            outcomes.push('discard');
        }
    }
    assert.equal(outcomes.length, 4);
});

test('two discards of one intent sent together both answer the original result, and of two intents sent together exactly one is admitted', async () => {
    const discards = async (id: string) => (await stored(id))?.receipts.filter((receipt: { kind: string }) => receipt.kind === 'discard').length;
    for (let n = 0; n < 4; n++) {
        // A Retry overlapping the original request, or two tabs with one buffered intent: the loser replays the tombstone's receipt.
        const review = await create(), body = mutation(review.item.revision);
        const [original, retried] = await Promise.all([discard(review.item.id, body), discard(review.item.id, body)]);
        assert.equal(original.status, 200, JSON.stringify(original)); assert.deepEqual(retried, original);
        assert.equal(await discards(review.item.id), 1);
        // Two administrators confirming at once: one discard is admitted, and the other finds the review discarded.
        const raced = await create(), answers = await Promise.all([discard(raced.item.id, mutation(raced.item.revision)), discard(raced.item.id, mutation(raced.item.revision))]);
        assert.deepEqual(answers.map(answer => answer.status).sort(), [200, 404], JSON.stringify(answers));
        assert.deepEqual(answers.find(answer => answer.status === 404), discarded);
        assert.equal(await discards(raced.item.id), 1);
    }
});

test('a discard whose lookup-record deletion fails writes nothing, and the same request is then admitted once', () => withLookup(async () => {
    const created = await createRouted(null), id = created.item.id, before = [await stored(id), await lookupRecord(id)];
    assert.equal((before[1] as { state?: string } | null)?.state, 'queued');
    const original = Collection.prototype.deleteOne, body = mutation(created.item.revision);
    // The tombstone is written, then deleting the lookup record fails: the whole discard transaction aborts.
    const failing = mock.method(Collection.prototype, 'deleteOne', async function (this: Collection, ...args: Parameters<Collection['deleteOne']>) {
        if (this.collectionName !== 'adminImportLookups') return original.apply(this, args);
        failing.mock.restore(); throw new Error('synthetic failure deleting the lookup record');
    });
    try { assert.deepEqual(await discard(id, body), { status: 503, body: { code: 'ADMIN_CATALOG_REVIEW_UNAVAILABLE' } }); } finally { mock.restoreAll(); }
    assert.deepEqual([await stored(id), await lookupRecord(id)], before);
    const admitted = await discard(id, body);
    assert.deepEqual([admitted.status, admitted.body.receipt.revision, await lookupRecord(id)], [200, created.item.revision + 1, null]);
    assert.deepEqual(await discard(id, body), admitted);
}));
